Problem statement:
Given n integers, print the largest sum of a non-empty contiguous subarray.

Input: the first line holds n (1 <= n <= 100000). The second line holds n integers a_1 .. a_n
(-1000000000 <= a_i <= 1000000000), separated by spaces.

Output: the maximum subarray sum followed by a newline. The subarray must contain at least one element,
so if every number is negative the answer is the largest (least negative) number. The answer may not fit
in a 32-bit int.

Sample input:
8
-2 1 -3 4 -1 2 1 -5

Sample output:
6

Student file kadane.c:
  1 | /* Maximum subarray sum with Kadane's algorithm, O(n). */
  2 | #include <stdio.h>
  3 | #include <stdlib.h>
  4 | 
  5 | /* Largest sum of a non-empty contiguous run of values[0..count-1]. */
  6 | static long long max_subarray(const long long *values, int count)
  7 | {
  8 |     long long best = values[0];
  9 |     long long ending_here = values[0];
 10 |     for (int i = 1; i < count; i++) {
 11 |         long long extended = ending_here + values[i];
 12 |         ending_here = extended > values[i] ? extended : values[i];
 13 |         if (ending_here > best) {
 14 |             best = ending_here;
 15 |         }
 16 |     }
 17 |     return best;
 18 | }
 19 | 
 20 | int main(void)
 21 | {
 22 |     int count;
 23 |     if (scanf("%d", &count) != 1 || count < 1) {
 24 |         return 1;
 25 |     }
 26 |     long long *values = malloc((size_t)count * sizeof *values);
 27 |     if (values == NULL) {
 28 |         return 1;
 29 |     }
 30 |     for (int i = 0; i < count; i++) {
 31 |         if (scanf("%lld", &values[i]) != 1) {
 32 |             free(values);
 33 |             return 1;
 34 |         }
 35 |     }
 36 |     printf("%lld\n", max_subarray(values, count));
 37 |     free(values);
 38 |     return 0;
 39 | }
